const P="runs/0193f7a2-6c1e-7a00-9b1a-2f4c8d9e0a11/differential-expression/output/de_results.csv";
const t = await tools.read_table({path:P});
const r=t.rows;
const up=r.filter(x=>x.padj<0.05&&x.log2FoldChange>0).length, dn=r.filter(x=>x.padj<0.05&&x.log2FoldChange<0).length;
const maxAbs=Math.max(...r.map(x=>Math.abs(x.log2FoldChange)));
const sum = await tools.write_derived({name:"de_summary",inputs:[P],rows:[
 {measure:"Genes in table",n:r.length},
 {measure:"Up-regulated (FDR < 0.05)",n:up},
 {measure:"Down-regulated (FDR < 0.05)",n:dn},
 {measure:"Largest absolute log2 fold change",n:Math.round(maxAbs*100)/100}]});
const isgSyms=['ISG15','MX1','IFIT1'];
const isg = await tools.write_derived({name:"named_isg_genes",inputs:[P],rows:r.filter(x=>isgSyms.includes(x.symbol)).map(x=>({symbol:x.symbol,gene_id:x.gene_id,log2FoldChange:Math.round(x.log2FoldChange*100)/100,padj:x.padj}))});
console.log(JSON.stringify(sum),JSON.stringify(isg));

const P="runs/0193f7a2-6c1e-7a00-9b1a-2f4c8d9e0a11/differential-expression/output/de_results.csv";
const S="report-sessions/thread-r/derived/de_summary", I="report-sessions/thread-r/derived/named_isg_genes";
const res=[];
res.push(await tools.set_title({title:"Treatment effect on gene expression: an interferon-response signal, with caveats"}));
const mv=(id,label,measure)=>({id,kind:"metric",label,value:{kind:"artifact-value",path:S,locator:{column:"n",rowFilter:{column:"measure",op:"eq",value:measure}}}});
res.push(await tools.add_block({block:{id:"sec-summary",kind:"section",title:"The treatment shifts hundreds of genes, and the named interferon genes go up",blocks:[
 mv("m-total","Genes in the DE table","Genes in the table"),
 mv("m-up","Up-regulated","Up-regulated (FDR < 0.05)"),
 mv("m-down","Down-regulated","Down-regulated (FDR < 0.05)"),
 {id:"t-summary",kind:"text",content:{prose:"Treated samples differ from controls in a few hundred genes, with more genes up than down. The three recognisable interferon-stimulated genes in the table (ISG15, MX1, IFIT1) are all up-regulated, which fits an interferon response. The evidence for the response is thin, though: only these three named genes support it, no pathway enrichment was run, and the run's written synthesis quotes fold changes that the results table does not reproduce (see the last section)."}}
]}}));
res.push(await tools.add_block({block:{id:"sec-volcano",kind:"section",title:"The volcano plot: the table holds only significant genes, and up-regulation dominates",blocks:[
 {id:"t-volcano",kind:"text",content:{prose:"Each point is a gene, plotted by log2 fold change (treated vs control) against adjusted p-value. Every gene in the exported table already passes FDR 0.05, so the plot shows only significant genes and cannot show the non-significant background. Read the right-hand side as up-regulated and the left-hand side as down-regulated."}},
 {id:"c-volcano",kind:"chart",chartType:"volcano",title:"Differential expression, treated vs control",caption:"Genes in the exported results table. The table is pre-filtered to adjusted p < 0.05, so non-significant genes are absent.",
  binding:{kind:"artifact-table",path:P,columns:["symbol","log2FoldChange","padj"],columnLabels:{symbol:"Gene",log2FoldChange:"log2 fold change",padj:"Adjusted p-value"},columnMeanings:{symbol:"identifier",log2FoldChange:"effect",padj:"p-value"}},
  encoding:{x:"log2FoldChange",p:"padj",label:"symbol"},thresholds:{significance:0.05}},
 {id:"t-volcano-after",kind:"text",content:{prose:"The strongest fold changes in this table belong to placeholder-named loci (LOC identifiers), not to annotated interferon genes. The interferon claim therefore rests on the named genes below."}}
]}}));
res.push(await tools.add_block({block:{id:"sec-isg",kind:"section",title:"ISG15, MX1 and IFIT1 are up, with moderate fold changes",blocks:[
 {id:"t-isg",kind:"text",content:{prose:"These three canonical interferon-stimulated genes are the only recognisable interferon markers in the table. All are strongly significant and increase in treated samples. Their fold changes are moderate, and they do not rank among the largest effects."}},
 {id:"tb-isg",kind:"table",title:"Named interferon-stimulated genes",caption:"Rows extracted from the DE results table.",binding:{kind:"artifact-table",path:I,columnLabels:{symbol:"Gene",gene_id:"Gene ID",log2FoldChange:"log2 fold change",padj:"Adjusted p-value"},columnMeanings:{symbol:"identifier",gene_id:"identifier",log2FoldChange:"effect",padj:"p-value"}}},
 {id:"cl-isg",kind:"claim",content:{prose:"ISG15 is up-regulated in treated samples."},bindings:[{kind:"artifact-value",path:I,locator:{column:"log2FoldChange",rowFilter:{column:"symbol",op:"eq",value:"ISG15"}}}]}
]}}));
res.push(await tools.add_block({block:{id:"sec-limits",kind:"section",title:"Limits and a discrepancy to resolve before this is shared",blocks:[
 {id:"t-limits",kind:"text",content:{prose:"Treat the conclusions as preliminary.",list:{ordered:false,items:[
  "The run's synthesis states 412 up and 198 down genes, and fold changes of 3.1 to 4.0 for ISG15, MX1 and IFIT1. The results table gives different counts, and much smaller fold changes for those genes. The largest absolute fold change anywhere in the table is shown in the card below. I report the table, since it is the pinned evidence, and the discrepancy needs to be checked at the source (for example a different filter or a different table version).",
  "The run reports three replicates per group, and one sample (C3) has a low library size. Power is limited and C3 may influence the result; I did not rerun the analysis with and without C3.",
  "The table is pre-filtered to significant genes, so I cannot assess the full distribution of effects, and no pathway or gene-set enrichment is in the evidence. 'Interferon response' is an interpretation from three named genes, not a tested result.",
  "Many adjusted p-values sit at an identical floor value, which suggests they are capped or simulated; I would check how they were computed before relying on their exact magnitude."]}}},
 mv("m-maxlfc","Largest absolute log2 fold change in the table","Largest absolute log2 fold change")
]}}));
console.log(JSON.stringify(res.map(x=>x.applied??x)));

const r=await tools.change_block({targetId:"t-limits",block:{id:"t-limits",kind:"text",content:{prose:"Treat the conclusions as preliminary.",list:{ordered:false,items:[
  "The run's synthesis states 412 up and 198 down genes, and fold changes of 3.1 to 4.0 for ISG15, MX1 and IFIT1. The results table gives different counts, and much smaller fold changes for those genes. The largest absolute fold change anywhere in the table is shown in the card below. I report the table, since it is the pinned evidence, and the discrepancy needs to be checked at the source (for example a different filter or a different table version).",
  "The run reports three replicates per group, and one sample (C3) has a low library size. Power is limited and C3 may influence the result; I did not rerun the analysis with and without C3.",
  "The table is pre-filtered to significant genes, so I cannot assess the full distribution of effects, and no pathway or gene-set enrichment is in the evidence. 'Interferon response' is an interpretation from three named genes, not a tested result.",
  "The adjusted p-values of the first rows rise in a smooth geometric progression from 1e-38, and fold changes step in regular increments. This pattern is unusual for real data, so I would check how the table was generated before relying on exact magnitudes."]}}}});
console.log(JSON.stringify(r));

