const out=[];
out.push(await tools.set_title({title:"Treatment drives a large, mostly up-regulated transcriptional response, with interferon-stimulated genes at the top"}));
out.push(await tools.add_block({block:{kind:"section",id:"sec-summary",title:"The treatment shifts 610 genes, and the interferon signal rests on three named genes",blocks:[
 {kind:"metric",id:"m-genes",label:"Genes called differentially expressed",value:{kind:"artifact-value",path:H,locator:{column:"genes_in_table",row:0}}},
 {kind:"metric",id:"m-up",label:"Up-regulated",value:{kind:"artifact-value",path:H,locator:{column:"genes_up",row:0}}},
 {kind:"metric",id:"m-down",label:"Down-regulated",value:{kind:"artifact-value",path:H,locator:{column:"genes_down",row:0}}},
 {kind:"metric",id:"m-isg",label:"Canonical interferon-stimulated genes named in the table",value:{kind:"artifact-value",path:H,locator:{column:"named_isgs",row:0}}},
 {kind:"text",id:"t-summary",content:{prose:"The treatment changes expression of 610 genes in the differential-expression table, with about twice as many going up as going down. The interferon-stimulated genes ISG15, MX1 and IFIT1 are among the most significant and all rise, which fits an interferon response. That reading is a hypothesis supported by three genes, not a tested conclusion: no pathway enrichment was run, and most of the other genes carry placeholder symbols. The run's own written summary also disagrees with the table on several numbers, which are listed below."}}
]}});
out.push(await tools.add_block({block:{kind:"section",id:"sec-volcano",title:"The volcano plot shows a broad response skewed toward up-regulation",blocks:[
 {kind:"text",id:"t-volcano",content:{prose:"Each point is one gene, with fold change on the horizontal axis and adjusted significance on the vertical axis. Look for the right-hand arm, which is larger than the left. Every gene in the table already passes the significance cut-off and a fold-change cut-off of two-fold, so the plot has no non-significant background cloud. The table gives no count of genes tested, so the fraction of the transcriptome that responded cannot be stated."}},
 {kind:"chart",id:"c-volcano",chartType:"volcano",title:"Differential expression after treatment",caption:"Genes in the differential-expression table. Dashed line: adjusted p-value of 0.05.",binding:{kind:"artifact-table",path:D,columnLabels:{log2FoldChange:"log2 fold change",padj:"Adjusted p-value",symbol:"Gene"},columnMeanings:{log2FoldChange:"effect",padj:"p-value",symbol:"identifier"}},encoding:{x:"log2FoldChange",p:"padj",label:"symbol"},thresholds:{significance:0.05,effect:1}}
]}});
out.push(await tools.add_block({block:{kind:"section",id:"sec-isg",title:"ISG15, MX1 and IFIT1 are up-regulated and are the only named interferon genes",blocks:[
 {kind:"text",id:"t-isg",content:{prose:"The three canonical interferon-stimulated genes in the table are all up-regulated, with IFIT1 showing the largest fold change of the three. They sit among the most significant genes, but significance is nearly saturated across the top of the table, so rank within it carries little information. The remaining genes are listed with placeholder LOC symbols, so I cannot say whether they are further interferon targets."}},
 {kind:"table",id:"tb-isg",title:"Canonical interferon-stimulated genes",caption:"Fold change and adjusted p-value for the three named interferon-stimulated genes.",binding:{kind:"artifact-table",path:I,columnLabels:{symbol:"Gene",gene_id:"Ensembl ID",log2FoldChange:"log2 fold change",padj:"Adjusted p-value"},columnMeanings:{symbol:"identifier",gene_id:"identifier",log2FoldChange:"effect",padj:"p-value"}}}
]}});
out.push(await tools.add_block({block:{kind:"section",id:"sec-limits",title:"The run's written summary disagrees with its table, and the design is small",blocks:[
 {kind:"text",id:"t-limits",content:{prose:"The run's synthesis reports 412 genes up and 198 down, and fold changes of 3.1 to 4.0 for ISG15, MX1 and IFIT1. The table gives 408 up and 202 down, and the three genes sit well below that range (see the table above); no gene in the table exceeds a fold change of about 3.1 in either direction. I report the table values, since the table is the primary output, but the synthesis should be corrected or the discrepancy explained before this goes beyond the lab. The synthesis also notes three replicates per group and a low library size for one sample, C3. With so few replicates, and with a sample of questionable depth, the effect sizes carry real uncertainty, and I did not check whether C3 drives any result. Also note that the adjusted p-values at the top of the table are extremely small, which is unusual for three replicates per group and worth checking against the model setup."}},
 {kind:"text",id:"t-next",content:{prose:"Next steps, in order of value:",list:{ordered:true,items:["Rerun differential expression with and without sample C3 and compare the gene lists.","Run pathway or gene-set enrichment on the full tested gene list, to test the interferon claim directly.","Annotate the placeholder LOC symbols, so that other interferon targets can be recognised.","Export the complete results table including non-significant genes, so that the volcano plot shows the full background."]}}}
]}});
